// The model NEVER free-forms a pipeline. It picks from plays the vertical declared and
// that survive hard filters. Pre-filtering here is what makes the choice auditable.
const b = $json.payload.brief;
const profile = $json.payload.profile || {};
const plays = profile.plays || [];
const channels = new Set((b.channels || []).map(c => c.channel));
const excluded = new Set(profile.channels?.excluded || []);

const eligible = [], rejected = [];
for (const play of plays) {
  const reasons = [];
  if (play.objective && b.objective && play.objective !== b.objective) reasons.push('objective_mismatch');
  const needsVideo = play.steps.some(s => s.tag === 'assemble.video');
  const wantsVideo = (b.assets?.required_kinds || []).includes('video') || [...channels].some(c => ['tiktok', 'youtube'].includes(c));
  if (needsVideo && !wantsVideo && (b.budget_minor_units ?? Infinity) < 500) reasons.push('video_not_requested_and_budget_thin');
  if ([...channels].every(c => excluded.has(c))) reasons.push('all_channels_excluded_by_vertical');
  (reasons.length ? rejected : eligible).push({ id: play.id, title: play.title, when: play.when, steps: play.steps.map(s => s.tag), eliminated_by: reasons[0] || null });
}

return [{ json: { eligible: eligible.slice(0, 5), rejected, brief: b, profile } }];

