// Expand the chosen play into a DAG of TAGS (not capability ids). Binding tags to concrete
// implementations happens later, per vertical, at execution time — that late binding is the
// whole reason one plan runs correctly for a plumber and a SaaS.
const sel = $json.output || $json;
const ctx = $('Enumerate Eligible Plays').first().json;
if (sel.no_fit) return [{ json: { no_fit: true, rationale: sel.rationale, action: 'ask_human' } }];

const play = (ctx.profile.plays || []).find(p => p.id === sel.chosen_play);
if (!play) throw new Error('VALIDATION_FAILED: selected play not found in profile: ' + sel.chosen_play);

const nodes = play.steps.map((s, i) => ({
  id: `n${i}`,
  tag: s.tag,
  params: { ...(s.with || {}), ...((sel.step_params || {})[s.tag] || {}) },
  parallel_group: s.parallel_group || null,
  depends_on: i === 0 ? [] : (s.parallel_group && play.steps[i - 1]?.parallel_group === s.parallel_group ? play.steps.slice(0, i).filter(x => x.parallel_group !== s.parallel_group).map((_, j) => `n${j}`).slice(-1) : [`n${i - 1}`])
}));

return [{ json: {
  plan_id: 'pln_' + $('Envelope In').first().json.trace_id.slice(0, 12),
  play: play.id,
  play_title: play.title,
  nodes,
  channel_allocation: sel.channel_allocation || ctx.brief.channels,
  confidence: sel.confidence,
  rationale: sel.rationale,
  expected_kpi: play.expected_kpi || null
} }];

// Drop lowest-priority channels and variant counts until the plan fits, and SAY what was
// dropped. A silently truncated campaign is indistinguishable from a broken one.
const plan = $('Expand to DAG').first().json;
const cap = $('Envelope In').first().json.budget?.cap_minor_units ?? 0;
const alloc = [...(plan.channel_allocation || [])].sort((a, b) => (a.priority ?? 3) - (b.priority ?? 3));
const dropped = [];
while (alloc.length > 1 && ($json.estimate_minor_units ?? 0) > cap) { dropped.push(alloc.pop()); }
for (const a of alloc) if ((a.variants ?? 1) > 1) a.variants = Math.max(1, Math.floor(a.variants / 2));
return [{ json: { ...plan, channel_allocation: alloc, rescoped: true, dropped_channels: dropped.map(d => d.channel), note: dropped.length ? `Budget cap ${cap} required dropping: ${dropped.map(d => d.channel).join(', ')}` : 'Variant counts reduced to fit budget.' } }];
